// الرئيسية باللغتين (نقطة بدء التطبيق المثبّت). صفحات الدول تُخزَّن عند زيارتها.
const HOME_PAGES = [
    "./",
    "./en/"
];

const NAVIGATION_TIMEOUT_MS = 2500;
const ASSET_TIMEOUT_MS = 4000;
const REFRESH_TIMEOUT_MS = 8000;

function fetchWithTimeout(request, timeoutMs) {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error('Network timeout')), timeoutMs);
        fetch(request).then(
            (response) => {
                clearTimeout(timer);
                resolve(response);
            },
            (err) => {
                clearTimeout(timer);
                reject(err);
            }
        );
    });
}

// مفتاح الصفحة في الكاش: بلا استعلام، و «/x/index.html» و «/x/» صفحة واحدة
function pageKey(url) {
    const u = new URL(url, self.location.href);
    u.search = '';
    u.hash = '';
    if (u.pathname.endsWith('/index.html')) u.pathname = u.pathname.slice(0, -'index.html'.length);
    return u.href;
}

function isPageRequest(request) {
    return request.mode === 'navigate' || (request.headers.get('accept') || '').includes('text/html');
}

// يجلب صفحة (طلب تنقّل أو رابط) ويخزّنها؛ يعيد الاستجابة، أو undefined عند الفشل.
// الاستجابة المعاد توجيهها (مثل ‎/qatar ← ‎/qatar/) لا تُخزَّن: لا يصح تقديمها لاحقاً لطلب تنقّل.
function fetchPage(input, timeoutMs) {
    const request = typeof input === 'string' ? new Request(input, { credentials: 'same-origin' }) : input;
    return fetchWithTimeout(request, timeoutMs)
        .then((response) => {
            if (!response || response.status !== 200 || response.redirected) return response;
            const clone = response.clone();
            return caches.open(PAGES_CACHE)
                .then(cache => cache.put(pageKey(request.url), clone))
                .then(() => response);
        })
        .catch(() => undefined);
}

self.addEventListener('install', (event) => {
    event.waitUntil((async () => {
        const shell = await caches.open(SHELL_CACHE);
        await shell.addAll(CRITICAL_ASSETS);
        await Promise.allSettled(OPTIONAL_ASSETS.map(url => shell.add(url)));
        await Promise.allSettled(HOME_PAGES.map(url => fetchPage(url, REFRESH_TIMEOUT_MS)));
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const pages = await caches.open(PAGES_CACHE);
        const keys = await caches.keys();
        const oldCaches = keys.filter(key => key.startsWith(CACHE_PREFIX) && key !== SHELL_CACHE && key !== PAGES_CACHE);

        // ترحيل الصفحات المخزّنة في كاش النسخ السابقة (قبل فصل الصفحات) حتى لا تضيع دون اتصال
        for (const name of oldCaches) {
            const old = await caches.open(name);
            for (const request of await old.keys()) {
                const path = new URL(request.url).pathname;
                if (!path.endsWith('/') && !path.endsWith('.html')) continue;
                const key = pageKey(request.url);
                if (!(await pages.match(key))) {
                    const response = await old.match(request);
                    if (response) await pages.put(key, response);
                }
            }
        }
        await Promise.all(oldCaches.map(name => caches.delete(name)));
        await self.clients.claim();

        // تحديث الصفحات المخزّنة لتطابق القشرة الجديدة (بأفضل جهد؛ دون اتصال تبقى النسخة السابقة)
        const cachedPages = await pages.keys();
        await Promise.allSettled(cachedPages.map(request => fetchPage(request.url, REFRESH_TIMEOUT_MS)));
    })());
});

// الصفحة تطلب تخزين نفسها ونسختها باللغة الأخرى (js/app.js)
self.addEventListener('message', (event) => {
    const data = event.data || {};
    if (data.type !== 'CACHE_PAGES' || !Array.isArray(data.urls)) return;
    const urls = data.urls.filter((url) => {
        try {
            return new URL(url).origin === self.location.origin;
        } catch (e) {
            return false;
        }
    });
    event.waitUntil(Promise.allSettled(urls.map(url => fetchPage(url, REFRESH_TIMEOUT_MS))));
});

self.addEventListener('fetch', (event) => {
    const request = event.request;
    if (request.method !== 'GET') return;

    const url = new URL(request.url);
    if (url.origin !== self.location.origin) return;

    // صفحات HTML: الشبكة أولاً بمهلة قصيرة، ثم النسخة المخزّنة عند ضعف التغطية أو انقطاعها
    if (isPageRequest(request)) {
        event.respondWith((async () => {
            const network = await fetchPage(request, NAVIGATION_TIMEOUT_MS);
            if (network) return network;
            return (await caches.match(pageKey(request.url), { cacheName: PAGES_CACHE })) || Response.error();
        })());
        return;
    }

    // الملفات الثابتة: Stale-While-Revalidate بمطابقة تامة للرابط، فلا تُخدَم نسخة قديمة (‎?v=قديم)
    // لصفحة تطلب نسخة جديدة. تجاهل ‎?v= ملاذ أخير فقط عند فشل الشبكة.
    event.respondWith((async () => {
        const update = fetchWithTimeout(request, ASSET_TIMEOUT_MS)
            .then(async (response) => {
                if (response && response.status === 200) {
                    const cache = await caches.open(SHELL_CACHE);
                    await cache.put(request, response.clone());
                }
                return response;
            })
            .catch(() => undefined);

        const exact = await caches.match(request);
        if (exact) {
            event.waitUntil(update);
            return exact;
        }
        return (await update) || (await caches.match(request, { ignoreSearch: true })) || Response.error();
    })());
});
